/**
 * An issue's own `archivedAt` isn't the whole story: a project archived with
 * `archiveIssues: false` freezes its issues without archiving them, and a
 * frozen issue must never be announced as overdue.
 */
async function isProjectArchived(
  orgId: OrgId,
  projectId: ProjectId,
  cache: Map<ProjectId, Project | null>,
): Promise<boolean> {
  if (!cache.has(projectId)) {
    cache.set(projectId, await projectRepo.findProjectById(orgId, projectId));
  }

  const project = cache.get(projectId) ?? null;
  return project !== null && isArchived(project);
}

